"use client";
import { useEffect, useState } from "react";
import { MessageCircle, ShieldCheck, Star } from "lucide-react";
import { getVendorReviews, getVendorReviewStats, replyToReview, type VendorReview } from "@/app/actions/vendor-reviews";
import { orderDate } from "@/lib/vendor/order-workspace";
import s from "@/components/vendor/business-workspace.module.css";
const PAGE_SIZE=25;
export default function ReviewsTab(){
 const [reviews,setReviews]=useState<VendorReview[]>([]),[stats,setStats]=useState<Awaited<ReturnType<typeof getVendorReviewStats>>|null>(null);
 const [type,setType]=useState<"all"|"product"|"service"|"store">("all"),[rating,setRating]=useState(0),[unanswered,setUnanswered]=useState(false),[search,setSearch]=useState(""),[page,setPage]=useState(0),[reload,setReload]=useState(0);
 const [loading,setLoading]=useState(true),[error,setError]=useState(""),[notice,setNotice]=useState(""),[replying,setReplying]=useState<string|null>(null),[reply,setReply]=useState(""),[saving,setSaving]=useState(false);
 useEffect(()=>{let active=true; const timer=setTimeout(()=>{setLoading(true);setError("");Promise.all([getVendorReviews({type,rating,unanswered,search,skip:page*PAGE_SIZE,take:PAGE_SIZE+1}),getVendorReviewStats()]).then(([rows,summary])=>{if(active){setReviews(rows);setStats(summary);}}).catch(()=>{if(active)setError("Your reviews could not be loaded. Please try again.");}).finally(()=>{if(active)setLoading(false);});},search?250:0);return()=>{active=false;clearTimeout(timer);};},[type,rating,unanswered,search,page,reload]);
 async function post(id:string){setSaving(true);setError("");try{const result=await replyToReview(id,reply);if("error"in result){setError(result.error);return;}setReplying(null);setReply("");setNotice("Your public reply has been saved.");setReload(n=>n+1);}catch{setError("Your reply could not be saved. Your text is still here; please try again.");}finally{setSaving(false);}}
 function filter(change:()=>void){change();setPage(0);}
 return <div className={s.stack} data-tour="reviews-list">
  <div className={s.grid} data-tour="review-summary">
   <section className={s.hero}><p className={s.label} style={{color:"#c6d5ba"}}>Your reputation</p><div className={s.row} style={{marginTop:14}}><strong className={s.metric}>{stats?.total?stats.average.toFixed(1):"—"}<span style={{fontSize:16,fontWeight:400}}> / 5</span></strong><Star size={30} aria-hidden/></div><p className={s.small} style={{marginTop:8}}>{stats?.total??"—"} customer reviews</p></section>
   <section className={s.card} data-tour="review-list"><div className={s.row}><div><p className={s.label}>Waiting for a reply</p><p className={s.metric} style={{margin:"10px 0"}}>{stats?.unanswered??"—"}</p></div><MessageCircle size={26} aria-hidden/></div><button className={s.link} onClick={()=>filter(()=>setUnanswered(true))}>Give customers a response →</button></section>
   <section className={s.card} aria-label="Rating breakdown">{[5,4,3,2,1].map(star=><button key={star} className={s.row} onClick={()=>filter(()=>setRating(rating===star?0:star))} aria-label={`Filter ${star} star reviews`} aria-pressed={rating===star} style={{width:"100%",gap:10,padding:"4px 0",cursor:"pointer"}}><span className={s.small}>{star} ★</span><span className={s.progress} style={{flex:1}}><span style={{width:`${stats?.total?((stats.breakdown[star]??0)/stats.total)*100:0}%`}}/></span><span className={s.small}>{stats?.breakdown[star]??0}</span></button>)}</section>
  </div>
  <section className={s.card}>
   <div className={s.row}><h2 className={s.heading}>Customer feedback</h2><label className={s.muted}><input type="checkbox" checked={unanswered} onChange={e=>filter(()=>setUnanswered(e.target.checked))}/> Needs a reply</label></div>
   <div className={s.toolbar}><input className={s.input} aria-label="Search reviews" placeholder="Search feedback, customer or listing…" value={search} onChange={e=>filter(()=>setSearch(e.target.value))}/><select aria-label="Review type" className={s.select} value={type} onChange={e=>filter(()=>setType(e.target.value as typeof type))}><option value="all">All reviews</option><option value="product">Products</option><option value="service">Services</option><option value="store">Store</option></select><select aria-label="Review rating" className={s.select} value={rating} onChange={e=>filter(()=>setRating(Number(e.target.value)))}><option value={0}>Any rating</option>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} stars</option>)}</select></div>
   {error&&<div role="alert" className={s.error}>{error} <button onClick={()=>setReload(n=>n+1)} className={s.link}>Retry loading</button></div>}{notice&&<p role="status" className={s.muted}>{notice}</p>}
   {loading?<p role="status" className={s.empty}>Loading feedback…</p>:!reviews.length?<div className={s.empty}><MessageCircle size={30} style={{margin:"0 auto 14px"}}/><h3 className={s.heading}>{search||rating||unanswered||type!=="all"?"No matching reviews":"Your next conversation starts here"}</h3><p>{stats?.total?"Try another filter to see more feedback.":"Customer reviews will appear here after they share their experience."}</p></div>:<div>{reviews.slice(0,PAGE_SIZE).map(review=><article className={s.divider} key={review.id}>
    <div className={s.row}><div className={s.row} style={{gap:12}}><span className={s.rating} aria-label={`${review.rating} out of 5 stars`}>{"★".repeat(review.rating)}{"☆".repeat(5-review.rating)}</span><time className={s.muted}>{orderDate(review.createdAt)}</time></div>{review.isVerifiedPurchase&&<span className={s.badge}><ShieldCheck size={12} style={{display:"inline",marginRight:5}} aria-hidden/>Verified purchase</span>}</div>
    <p className={s.muted} style={{margin:"8px 0 12px"}}><strong>{review.customer.fullName}</strong> · {review.productName??review.serviceName??"Your store"}</p>
    {review.title&&<h3 className={s.heading} style={{fontSize:16}}>{review.title}</h3>}{review.body&&<p className={s.reviewBody}>{review.body}</p>}
    {review.vendorReply&&<div className={s.reply}><p className={s.label}>Your public reply</p><p className={s.reviewBody} style={{marginTop:6}}>{review.vendorReply}</p></div>}
    {replying===review.id?<div className={s.stack} style={{gap:10,marginTop:16}}><label htmlFor={`reply-${review.id}`} className={s.label}>Your public reply</label><textarea id={`reply-${review.id}`} className={s.textarea} value={reply} onChange={e=>setReply(e.target.value)} maxLength={2000} rows={4} disabled={saving} placeholder="Thank the customer, acknowledge their experience and offer a helpful next step."/><div className={s.row}><span className={s.muted}>{reply.length}/2,000 · Visible to customers</span><div className={s.miniLinks} style={{margin:0}}><button className={s.secondary} disabled={saving} onClick={()=>setReplying(null)}>Cancel</button><button className={s.button} disabled={saving||!reply.trim()} onClick={()=>void post(review.id)}>{saving?"Saving…":"Save public reply"}</button></div></div></div>:<button data-tour="review-response" className={s.link} style={{marginTop:14}} disabled={saving} onClick={()=>{setReplying(review.id);setReply(review.vendorReply??"");setNotice("");}}>{review.vendorReply?"Edit your reply":"Reply to this customer"}</button>}
   </article>)}</div>}
   {(page>0||reviews.length>PAGE_SIZE)&&<nav aria-label="Review pages" className={s.row} style={{marginTop:20}}><button className={s.secondary} disabled={!page||loading} onClick={()=>setPage(p=>p-1)}>Previous</button><span className={s.muted}>Page {page+1}</span><button className={s.secondary} disabled={reviews.length<=PAGE_SIZE||loading} onClick={()=>setPage(p=>p+1)}>Next</button></nav>}
  </section>
 </div>;
}
